class_name EnemyRoleDefinition
extends Resource

## Canon slice roles: pressure / armored / harasser (Combat & Arsenal).
## Combat fields are typed placeholders until labs/combat lands results.

@export var role_id: StringName = &""
@export var display_name: String = ""
@export var hp: float = 100.0
@export var speed: float = 3.0

class_name MechDefinition
extends Resource

## One mech, no second gunner, fixed loadout (VS-6 canon). Absence of
## customization fields is deliberate design, not an omission.

@export var display_name: String = ""
@export var loadout: PackedStringArray = PackedStringArray(["rotary", "rockets"])
@export var hp: float = 800.0
@export var speed: float = 4.0

class_name MissionDefinition
extends Resource

## Authoritative data contract for one operation. Gameplay systems read this;
## nobody hardcodes mission numbers in scripts. Numeric values are starting
## hypotheses, not final balance (Proof Contract change-control rule).

@export var id: StringName = &""
@export var display_name: String = ""
## Canon slice = duo; 1 is the local solo debug run (Prototype Architecture).
## Final player-count model is a VS-3 decision:
## Obsidian/06_Decisions/08_VS1_Core_And_Players_Fields_Decision.md
@export var player_count: int = 2
@export var lanes: Array[StringName] = [&"A", &"B", &"C"]
@export var core_hp: float = 500.0
@export var ex_quota: float = 1500.0
## Deprecated compatibility surface only. Wave/simulation canon lives in
## res://data/missions/mission_default.json; keep this untyped Resource array
## so older .tres assets can still deserialize without a dead WaveDefinition.
@export var waves: Array[Resource] = []


static func load_default() -> MissionDefinition:
	return load("res://data/default_mission.tres") as MissionDefinition

class_name TurretDefinition
extends Resource

## Canon slice roles: mg (sustained DPS) / cc (control). Limited ammo is canon;
## capacity numbers are hypotheses.

@export var role_id: StringName = &""
@export var display_name: String = ""
@export var ammo_capacity: int = 120
@export var damage: float = 10.0
@export var fire_interval: float = 0.2
